1060: \paragraph{RR-MoA pseudocode.}
1061: \begin{algorithm}[h]
1062: \caption{RR-MoA: Raw-Routed Mixture of Adapters with Top-$k$ sparse routing}
1063: \label{alg:rrmoa}
1064: \begin{algorithmic}[1]
1065: \REQUIRE TSFM $f_\theta$ (default: strictly frozen; optional: last-$\ell$ blocks unfrozen), raw input $\mathbf{X}_\text{raw}\in\mathbb{R}^{B\times L}$, $K$ expert adapters, sparsity $k\leq K$
1066: \STATE $\mathbf{H}\leftarrow f_\theta(\mathbf{X}_\text{raw})$ \hfill \COMMENT{Frozen default: no gradients through $\theta$; for last-$\ell$/all unfreezing (Table~\ref{tab:rrmoa}), the unfrozen blocks receive gradients normally}
1067: \STATE $\mathbf{g}\leftarrow G_\psi(\mathbf{X}_\text{raw})$ \hfill \COMMENT{Raw-signal gate logits, $\mathbf{g}\in\mathbb{R}^{B\times K}$}
1068: \STATE $\mathcal{T}\leftarrow \mathrm{TopK}(\mathbf{g},\,k)$ \hfill \COMMENT{Per-sample indices of the $k$ selected experts}
1069: \STATE $\widetilde{\mathbf{w}}\leftarrow \mathrm{softmax}_{\mathcal{T}}(\mathbf{g})$ \hfill \COMMENT{Renormalized over selected experts only}
1070: \STATE \textbf{for each}\ $j \in \mathcal{T}$\ \textbf{do}
1071: \STATE \quad $\mathbf{o}_j\leftarrow \text{Expert}_j(\mathbf{H})$ \hfill \COMMENT{Only the $k$ selected experts execute}
1072: \STATE \textbf{end for}
1073: \STATE $\mathbf{Y}\leftarrow \sum_{j\in\mathcal{T}}\widetilde{w}_j\cdot \mathbf{o}_j$
1074: \RETURN $\mathbf{Y}$
1075: \end{algorithmic}

